package com.spaceagent.platform.automation.application;
import com.spaceagent.platform.automation.api.AutomationEventExecutionApplicationApi;import com.spaceagent.platform.automation.domain.AutomationTriggerRepository;import com.spaceagent.shared.time.TimeProvider;import java.time.temporal.ChronoUnit;import org.slf4j.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;
@Component @ConditionalOnProperty(prefix="platform",name="persistence",havingValue="postgres") public class AutomationEventDispatchWorker{private static final Logger LOG=LoggerFactory.getLogger(AutomationEventDispatchWorker.class);private final AutomationTriggerRepository repository;private final AutomationEventExecutionApplicationApi events;private final TimeProvider time;public AutomationEventDispatchWorker(AutomationTriggerRepository repository,AutomationEventExecutionApplicationApi events,TimeProvider time){this.repository=repository;this.events=events;this.time=time;}@Scheduled(fixedDelayString="${platform.automation.event-dispatch-poll-delay-ms:500}")public void poll(){for(int i=0;i<20&&dispatchOne();i++){}}public boolean dispatchOne(){var now=time.now();var occurrence=repository.claimNextDispatchable(now.minus(60,ChronoUnit.SECONDS),now).orElse(null);if(occurrence==null)return false;try{events.dispatch(new AutomationEventExecutionApplicationApi.DispatchCommand(occurrence.id(),null,occurrence.revision()));}catch(RuntimeException error){LOG.warn("Automation occurrence dispatch failed safely: occurrenceId={}, type={}",occurrence.id(),error.getClass().getSimpleName());}return true;}}
